{
  "title": "The Glass Diver's Rescue",
  "gate_token": "moA4S6lKgC5PfFVgS9IMjw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer leads the glass_diver to the ruined city gates.",
      "visual_description": "Two figures stand before massive iron gates wrapped in rusted chains, broken royal banners flapping in the wind above.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle_lamp warns them about the cursed tower ahead.",
      "visual_description": "Inside a crumbling archway, the oracle_lamp's flame flickers as its single eye glows, casting shadows on stone walls.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "A tin_fox scampers through the rubble to scout the path.",
      "visual_description": "The small metal fox with a key-wind tail darts between fallen pillars, blue glass eyes reflecting the ruins.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Mara unfolds her map while the glass_diver peers through a broken window.",
      "visual_description": "Mara traces ink-stained fingers over a worn map as the glass_diver's diving helmet catches the pale light from a shattered window pane.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The oracle_lamp illuminates a cursed tower gate.",
      "visual_description": "A heavy wooden door covered in glowing runes is lit by the lamp's flame; the tin_fox sniffs the threshold.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass_diver attempts to swim through a reflection in a murky pool.",
      "visual_description": "Kneeling by a stagnant fountain, the glass_diver touches the water's surface, which ripples like a mirror, while Mara watches anxiously.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The sleeping_tax_collector is found dozing on a pile of ledgers.",
      "visual_description": "In a collapsed guardhouse, the tax collector snores with a ledger book as a pillow, stamps stuck to his sleeves and papers scattered around.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "Mara and the glass_diver attempt to wake the sleeping_tax_collector.",
      "visual_description": "Mara shakes the collector's shoulder while the glass_diver taps the diving helmet against a stone wall, echoing in the small room.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "The tin_fox returns with news of armored patrols ahead.",
      "visual_description": "The clockwork fox dashes back, its gears clicking, and points its snout down a narrow alley where shadows of figures move.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle_lamp warns of a rumored dragon in the tower.",
      "visual_description": "The lamp's flame burns low as it whispers; the group huddles behind a collapsed wall, the tower looming in the distance.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The glass_diver uses a window reflection to bypass a magic door.",
      "visual_description": "Pressing his helmet against a cracked window, the glass_diver shimmers and steps through into a dim corridor, leaving the door untouched.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Mara finds a secret passage on her map.",
      "visual_description": "By lantern light, Mara studies her map and points to a hidden route marked with fading ink, while the tin_fox peers over her shoulder.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The sleeping_tax_collector wakes briefly and gives a useless stamp.",
      "visual_description": "Rubbing his eyes, the collector stamps a blank piece of paper and hands it to Mara before slumping back to sleep.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Armored patrols corner the group in a courtyard.",
      "visual_description": "Figures in dark armor clank into a courtyard with broken statues; Mara pushes everyone behind a fallen pillar.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The glass_diver leads the escape through a series of reflective puddles.",
      "visual_description": "Leaping across rain-filled depressions, the glass_diver creates shimmering portals; the others follow, stepping through each reflection.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The group reaches the final bridge.",
      "visual_description": "A long stone bridge spans a chasm, its rails adorned with tattered banners; the far side promises safety, but the bridge creaks under their weight.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The oracle_lamp's flame flares as the bridge begins to collapse.",
      "visual_description": "Stones crumble from the bridge's edge; the oracle_lamp blazes bright, illuminating the broken path ahead as they run.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes as the bridge falls behind them.",
      "visual_description": "Leaping onto solid ground, they watch the bridge crash into the chasm; the glass_diver's helmet reflects the ruined city behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    }
  ]
}

